return $input.all().map(item => {
  const r = item.json;
  const timezone = r.site_timezone || 'Europe/Paris';
  const date = new Date(r.debut);

  const dateFormatee = new Intl.DateTimeFormat('fr-FR', {
    timeZone: timezone,
    dateStyle: 'full'
  }).format(date);

  const heureFormatee = new Intl.DateTimeFormat('fr-FR', {
    timeZone: timezone,
    hour: '2-digit',
    minute: '2-digit'
  }).format(date);

  const nomComplet = [r.prenom, r.nom].filter(Boolean).join(' ');
  const manageUrl =
    `http://localhost:5680/manage-appointment?token=${r.token_gestion}`;

  let rappelTexte;

  switch (r.type) {
    case 'RAPPEL_J7':
      rappelTexte =
        'Votre rendez-vous consulaire est prévu dans 7 jours.';
      break;

    case 'RAPPEL_J1':
      rappelTexte =
        'Votre rendez-vous consulaire est prévu demain.';
      break;

    case 'RAPPEL_H2':
      rappelTexte =
        'Votre rendez-vous consulaire est prévu dans environ 2 heures.';
      break;

    default:
      throw new Error(`Type de rappel non pris en charge : ${r.type}`);
  }

  return {
    json: {
      ...r,
      email_subject:
        `Rappel rendez-vous ${r.service_nom} - ${r.reference}`,
      email_text: `Bonjour ${nomComplet},

${rappelTexte}

Référence : ${r.reference}
Service : ${r.service_nom}
Lieu : ${r.site_nom}
Adresse : ${r.site_adresse || 'À confirmer'}
Date : ${dateFormatee}
Heure : ${heureFormatee}

Merci de vous présenter à l'heure prévue avec les documents nécessaires à votre démarche.

Gérer, annuler ou replanifier votre rendez-vous :
${manageUrl}

Cordialement,

Service consulaire`
    }
  };
});
